// ============================================
// CALCULATE CLARIFICATION RATE
// ============================================

const data = $input.first().json;

// Handle empty results
if (!data || !data.total || data.total === 0) {
  return [{
    json: {
      status: 'no_data',
      message: 'No intent data in the last hour',
      checked_at: new Date().toISOString()
    }
  }];
}

// Calculate rate
const total = data.total;
const clarificationCount = data.clarification_count || 0;
const clarificationRate = (clarificationCount / total) * 100;

// Determine severity
let severity = 'OK';
if (clarificationRate > 50) {
  severity = 'CRITICAL';
} else if (clarificationRate > 30) {
  severity = 'WARNING';
}

// Calculate per-domain breakdown
const domainStats = {};
if (data.by_domain) {
  for (const item of data.by_domain) {
    const domain = item.domain || 'unknown';
    if (!domainStats[domain]) {
      domainStats[domain] = { total: 0, clarifications: 0 };
    }
    domainStats[domain].total++;
    if (item.needed_clarification) {
      domainStats[domain].clarifications++;
    }
  }
}

return [{
  json: {
    total_requests: total,
    clarification_count: clarificationCount,
    clarification_rate: Math.round(clarificationRate * 100) / 100,
    severity: severity,
    threshold_warning: 30,
    threshold_critical: 50,
    domain_breakdown: domainStats,
    checked_at: new Date().toISOString()
  }
}];

// Prepare alert data for MongoDB
const data = $input.first().json;

return [{
  json: {
    alert_type: 'clarification_high',
    severity: data.severity,
    clarification_rate: data.clarification_rate,
    total_requests: data.total_requests,
    clarification_count: data.clarification_count,
    domain_breakdown: JSON.stringify(data.domain_breakdown),
    created_at: new Date()
  }
}];

// ============================================
// FORMAT DISCORD MESSAGE
// ============================================

const data = $('Calculate Rate').first().json;
const emoji = data.severity === 'CRITICAL' ? '🚨' : '⚠️';
const color = data.severity === 'CRITICAL' ? 0xFF0000 : 0xFFA500;

// Build domain breakdown text
let domainText = '';
for (const [domain, stats] of Object.entries(data.domain_breakdown || {})) {
  const rate = stats.total > 0 ? ((stats.clarifications / stats.total) * 100).toFixed(1) : 0;
  domainText += `• **${domain}**: ${rate}% (${stats.clarifications}/${stats.total})\n`;
}

return [{
  json: {
    embeds: [{
      title: `${emoji} Intent Clarification ${data.severity}`,
      description: `Le taux de clarification a dépassé le seuil dans la dernière heure.`,
      color: color,
      fields: [
        {
          name: 'Taux de clarification',
          value: `${data.clarification_rate}%`,
          inline: true
        },
        {
          name: 'Seuil',
          value: `${data.severity === 'CRITICAL' ? '>50%' : '>30%'}`,
          inline: true
        },
        {
          name: 'Total requêtes',
          value: `${data.total_requests}`,
          inline: true
        },
        {
          name: 'Détail par domaine',
          value: domainText || 'Aucune donnée',
          inline: false
        }
      ],
      timestamp: new Date().toISOString()
    }]
  }
}];
